import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatMain.css";

const ChatMain = ({ selectedConversation, user }) => {
  const [messages, setMessages] = useState([]);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const fetchMessages = async () => {
      if (!selectedConversation) return;

      try {
        const token = localStorage.getItem("token");
        const res = await axios.get(`http://localhost:5000/api/messages/${selectedConversation._id}`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        setMessages(res.data);
      } catch (err) {
        console.error("Error fetching messages:", err);
      }
    };

    fetchMessages();
  }, [selectedConversation]);

  const handleSend = async () => {
    if (!message.trim()) return;
    if (!selectedConversation) {
      console.warn("No conversation selected.");
      return;
    }

    const recipientId = selectedConversation.members.find(
      (id) => id !== user._id
    );
    if (!recipientId) {
      console.warn("Recipient not found.");
      return;
    }

    try {
      const token = localStorage.getItem("token");
      await axios.post(
        "http://localhost:5000/api/messages",
        {
          conversationId: selectedConversation._id,
          sender: user._id,
          text: message,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setMessages((prev) => [
        ...prev,
        {
          sender: user._id,
          text: message,
          createdAt: new Date().toISOString(),
        },
      ]);
      setMessage("");
    } catch (err) {
      console.error("Error sending message:", err);
    }
  };

  return (
    <div className="chat-main">
      <h3>
        {selectedConversation ? "Conversation" : "No conversation selected"}
      </h3>

      <div className="chat-messages">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={`chat-bubble ${
              msg.sender === user._id ? "sent" : "received"
            }`}
          >
            <p>{msg.text}</p>
            <span className="timestamp">
              {new Date(msg.createdAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
      </div>

      <div className="chat-input">
        <input
          type="text"
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          placeholder="Type your message..."
        />
        <button onClick={handleSend}>Send</button>
      </div>
    </div>
  );
};

export default ChatMain;
